  INDEX `fk_Armament_Provision_Armament1_idx` (`id_armament` ASC) VISIBLE,
  CONSTRAINT `fk_Armament_Provision_Military_Unit1`
    FOREIGN KEY (`id_military_unit`)
    REFERENCES `Военный_округ`.`Military_Unit` (`id_military_unit`)
    ON DELETE CASCADE
    ON UPDATE NO ACTION,
  CONSTRAINT `fk_Armament_Provision_Armament1`
    FOREIGN KEY (`id_armament`)
    REFERENCES `Военный_округ`.`Armament` (`id_armament`)
    ON DELETE CASCADE
    ON UPDATE NO ACTION)
ENGINE = InnoDB;


