-- -----------------------------------------------------
-- View `Военный_округ`.`Serviceman_Full_Info`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `Военный_округ`.`Serviceman_Full_Info`;
USE `Военный_округ`;
CREATE  OR REPLACE VIEW `Serviceman_Full_Info` AS
SELECT 
    s.id_serviceman,
    CONCAT(s.surname, ' ', s.first_name, ' ', COALESCE(s.patronymic, '')) AS full_name,
    s.birth_date,
    r.name AS `rank`,
    rc.name AS rank_category,
    su.name AS subunit,
    ut.name AS unit_type,
    mu.name AS military_unit,
    su.id_subunit,
    su.id_military_unit
FROM Serviceman s
JOIN `Rank` r ON s.id_rank = r.id_rank
JOIN Rank_Category rc ON r.id_rank_category = rc.id_rank_category
JOIN Military_Subunit su ON s.id_subunit = su.id_subunit
JOIN Unit_Type ut ON su.id_unit_type = ut.id_unit_type
LEFT JOIN Military_Unit mu ON su.id_military_unit = mu.id_military_unit;

-- -----------------------------------------------------
-- View `Военный_округ`.`Subunit_Hierarchy`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `Военный_округ`.`Subunit_Hierarchy`;
USE `Военный_округ`;
CREATE  OR REPLACE VIEW Subunit_Hierarchy AS
WITH RECURSIVE subunit_tree AS (
    SELECT 
        su.id_subunit,
        su.name,
        ut.name AS unit_type,
        su.id_parent,
        su.id_military_unit,
        su.id_commander,
        CONCAT(COALESCE(s.surname, ''), ' ', COALESCE(s.first_name, '')) AS commander_name,
        0 AS depth_level,
        CAST(su.name AS CHAR(500)) AS path
    FROM Military_Subunit su
    JOIN Unit_Type ut ON su.id_unit_type = ut.id_unit_type
    LEFT JOIN Serviceman s ON su.id_commander = s.id_serviceman
    WHERE su.id_parent IS NULL
    
    UNION ALL
    
    SELECT 
        su.id_subunit,
        su.name,
        ut.name AS unit_type,
        su.id_parent,
        su.id_military_unit,
        su.id_commander,
        CONCAT(COALESCE(s.surname, ''), ' ', COALESCE(s.first_name, '')) AS commander_name,
        st.depth_level + 1,
        CONCAT(st.path, ' -> ', su.name)
    FROM Military_Subunit su
    JOIN Unit_Type ut ON su.id_unit_type = ut.id_unit_type
    JOIN subunit_tree st ON su.id_parent = st.id_subunit
    LEFT JOIN Serviceman s ON su.id_commander = s.id_serviceman
)
SELECT * FROM subunit_tree;

-- -----------------------------------------------------
-- View `Военный_округ`.`Unit_Equipment_Summary`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `Военный_округ`.`Unit_Equipment_Summary`;
USE `Военный_округ`;
CREATE  OR REPLACE VIEW Unit_Equipment_Summary AS
SELECT 
    mu.id_military_unit,
    mu.name AS unit_name,
    ec.name AS equipment_category,
    e.model,
    e.id_equipment,
    ep.quantity
FROM Military_Unit mu
JOIN Equipment_Provision ep ON mu.id_military_unit = ep.id_military_unit
JOIN Equipment e ON ep.id_equipment = e.id_equipment
JOIN Equipment_Category ec ON e.id_equipment_category = ec.id_equipment_category;

-- -----------------------------------------------------
-- View `Военный_округ`.`Unit_Armament_Summary`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `Военный_округ`.`Unit_Armament_Summary`;
USE `Военный_округ`;
CREATE  OR REPLACE VIEW Unit_Armament_Summary AS
SELECT 
    mu.id_military_unit,
    mu.name AS unit_name,
    ac.name AS armament_category,
    a.name AS armament_name,
    a.id_armament,
    ap.quantity
FROM Military_Unit mu
JOIN Armament_Provision ap ON mu.id_military_unit = ap.id_military_unit
JOIN Armament a ON ap.id_armament = a.id_armament
JOIN Armament_Category ac ON a.id_armament_category = ac.id_armament_category;

-- -----------------------------------------------------
-- View `Военный_округ`.`Unit_Facilities`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `Военный_округ`.`Unit_Facilities`;
USE `Военный_округ`;
CREATE  OR REPLACE VIEW Unit_Facilities AS
SELECT 
    mu.id_military_unit,
    mu.name AS unit_name,
    f.name AS facility_name,
    ft.name AS facility_type,
    f.id_facility,
    fa.start_date,
    fa.end_date
FROM Military_Unit mu
JOIN Facility_Assignment fa ON mu.id_military_unit = fa.id_military_unit
JOIN Facility f ON fa.id_facility = f.id_facility
JOIN Facility_Type ft ON f.id_facility_type = ft.id_facility_type;
USE `Военный_округ`;

DELIMITER $$
USE `Военный_округ`$$
CREATE DEFINER = CURRENT_USER TRIGGER `Военный_округ`.`check_commander_rank_insert` BEFORE INSERT ON `Military_Subunit` FOR EACH ROW
BEGIN
    DECLARE cmd_rank_cat VARCHAR(50);
    
    IF NEW.id_commander IS NOT NULL THEN
        SELECT rc.name INTO cmd_rank_cat
        FROM Serviceman s
        JOIN `Rank` r ON s.id_rank = r.id_rank
        JOIN Rank_Category rc ON r.id_rank_category = rc.id_rank_category
        WHERE s.id_serviceman = NEW.id_commander;
        
        IF cmd_rank_cat = 'Рядовой и сержантский состав' THEN
            IF (SELECT name FROM Unit_Type WHERE id_unit_type = NEW.id_unit_type) 
               NOT IN ('Взвод', 'Отделение') THEN
                SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Рядовой и сержантский состав может командовать только взводом или отделением';
            END IF;
        END IF;
    END IF;
END$$

USE `Военный_округ`$$
CREATE DEFINER = CURRENT_USER TRIGGER `Военный_округ`.`check_commander_rank_update` BEFORE UPDATE ON `Military_Subunit` FOR EACH ROW
BEGIN
DECLARE cmd_rank_cat VARCHAR(50);
    
    IF NEW.id_commander IS NOT NULL THEN
        SELECT rc.name INTO cmd_rank_cat
        FROM Serviceman s
        JOIN `Rank` r ON s.id_rank = r.id_rank
        JOIN Rank_Category rc ON r.id_rank_category = rc.id_rank_category
        WHERE s.id_serviceman = NEW.id_commander;
        
        IF cmd_rank_cat = 'Рядовой и сержантский состав' THEN
            IF (SELECT name FROM Unit_Type WHERE id_unit_type = NEW.id_unit_type) 
               NOT IN ('Взвод', 'Отделение') THEN
                SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Рядовой и сержантский состав может командовать только взводом или отделением';
            END IF;
        END IF;
    END IF;
END$$

USE `Военный_округ`$$
CREATE DEFINER = CURRENT_USER TRIGGER `Военный_округ`.`check_general_info_insert` BEFORE INSERT ON `General_Info` FOR EACH ROW
BEGIN
IF EXISTS(SELECT 1 FROM Officer_Info WHERE id_serviceman = NEW.id_serviceman)
       OR EXISTS(SELECT 1 FROM Enlisted_Info WHERE id_serviceman = NEW.id_serviceman) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'У военнослужащего уже есть запись в другой таблице дополнительной информации';
    END IF;
END$$

USE `Военный_округ`$$
